        if 0 <= r < h and 0 <= c < w and out[r][c] == bg:
            out[r][c] = color

    # Find the strongest diagonal alignment among the 1s.
    groups = {}
    for slope in (1, -1):
        by_key = {}
        for r, c in ones:
            key = c - slope * r
            by_key.setdefault(key, []).append((r, c))
        for key, pts in by_key.items():
            if len(pts) >= 2:
