            rr, cc = r + dr, c + dc
            while 0 <= rr < h and 0 <= cc < w:
                draw(rr, cc, 1)
                rr += dr
                cc += dc

    # 6s trace the perpendicular diagonal. With several 1s, only 6s
    # lying on the connected 1 diagonal act as starting points.
